it('registers through its service provider and merges its config', function () {
    TestApp::boot();
    expect(config('connectors.gmail-inbox.mode'))->toBe('auto');
    expect(config('connectors.gmail-inbox.credentials'))->toBeArray();
});

it('fakes history_list and records it for assertSent', function () {
    TestApp::boot();
    GmailInbox::fake();
    $config = [
        'userId' => 'example-userId',
        'startHistoryId' => 'example-startHistoryId',
        'historyTypes' => 'messageAdded',
        'labelId' => 'example-labelId',
        'maxResults' => 500,
        'pageToken' => 'example-pageToken',
    ];
    $result = GmailInbox::call('history_list', $config);

    expect($result->mode->value)->toBe('fake');
    GmailInbox::assertSent('history_list', fn (array $sent): bool => $sent == $config);
    GmailInbox::assertNotSent('no_such_operation');
    GmailInbox::assertSentCount(1);
});

it('refuses a forged message_received delivery before the app sees it', function () {
    $app = TestApp::boot();
    $app['router']->gmailInboxMessageReceived('/hooks/gmail-inbox');
    $response = TestApp::dispatch($app, Request::create('/hooks/gmail-inbox', 'POST', server: ['CONTENT_TYPE' => 'application/json'], content: '{"forged":true}'));

    expect($response->getStatusCode())->toBe(401);
});
